# Child source views a parent row requires (supplementary-review-s3 S3-C1, first part: SD0213, SD0226,
# SD0236, SD0270). Parent SD id -> list of (card key, display name, desc, [(source label, path)]). Each child is a
# nonspatial card placed right after its parent. Wording comes from the chapter rows of coverage-nt.md.
CHILDREN = {
    # S3-C1: Synoptic calls, healings and crossings, one view per chapter from the accepted NT chapter ledger, in source order (2/nt)
    'SD0214': [
        ('NTE-calls-and-healings-matt-9', 'Calls, healings and crossings (Matthew 9)', P + 'Matthew 9: Jesus returns to his own city; a paralytic is healed, Matthew is called, and a ruler’s daughter and a woman are healed. The ruler is unnamed here. Two blind men and a dumb man follow in 9:27–34.', [('Matthew 9', 'nt/matt/9')]),
        ('NTE-calls-and-healings-matt-12', 'Calls, healings and crossings (Matthew 12)', P + 'Matthew 12: Sabbath controversies, a healing and teaching on Jesus’s family; Jonah and Nineveh and the queen of the south are recalled as examples, not drawn as places.', [('Matthew 12', 'nt/matt/12')]),
        ('NTE-calls-and-healings-mark-1', 'Calls, healings and crossings (Mark 1)', P + 'Mark 1: John baptizes in the wilderness at the Jordan; Jesus comes from Nazareth, is tempted, calls fishermen, and teaches and heals at Capernaum before wider preaching in Galilee.', [('Mark 1', 'nt/mark/1')]),
        ('NTE-calls-and-healings-mark-2', 'Calls, healings and crossings (Mark 2)', P + 'Mark 2: a healing in a house at Capernaum, Levi’s call, a meal and Sabbath disputes. Mark’s naming of Abiathar is kept beside 1 Samuel 21’s Ahimelech; the difference is not silently resolved.', [('Mark 2', 'nt/mark/2')]),
        ('NTE-calls-and-healings-mark-3', 'Calls, healings and crossings (Mark 3)', P + 'Mark 3: crowds from several regions gather by the sea; Jesus appoints the Twelve on a mountain and defines his family. The mountain is not located.', [('Mark 3', 'nt/mark/3')]),
        ('NTE-calls-and-healings-mark-4', 'Calls, healings and crossings (Mark 4)', P + 'Mark 4: teaching from a boat beside the sea, including seed parables; a crossing ends with the calming of a storm. No storm track is drawn.', [('Mark 4', 'nt/mark/4')]),
        ('NTE-calls-and-healings-mark-5', 'Calls, healings and crossings (Mark 5)', P + 'Mark 5: across the sea in the country of the Gadarenes, Jesus frees a man possessed, who then proclaims in the Decapolis; after the return crossing come Jairus’s daughter and a woman’s healing. News of the daughter’s death arrives after Jairus’s request; this order is kept beside Matthew 9.', [('Mark 5', 'nt/mark/5')]),
        ('NTE-calls-and-healings-luke-4', 'Calls, healings and crossings (Luke 4)', P + 'Luke 4: in Luke’s order the temptation ends at Jerusalem; rejection at Nazareth and healings at Capernaum follow.', [('Luke 4', 'nt/luke/4')]),
        ('NTE-calls-and-healings-luke-5', 'Calls, healings and crossings (Luke 5)', P + 'Luke 5: a catch at the lake of Gennesaret brings Simon, James and John into discipleship; a leper and a paralytic are healed and Levi is called.', [('Luke 5', 'nt/luke/5')]),
        ('NTE-calls-and-healings-luke-6', 'Calls, healings and crossings (Luke 6)', P + 'Luke 6: the Twelve are chosen after prayer on a mountain; Jesus teaches on a level place, with crowds from Judea, Jerusalem and the coast of Tyre and Sidon.', [('Luke 6', 'nt/luke/6')]),
        ('NTE-calls-and-healings-luke-7', 'Calls, healings and crossings (Luke 7)', P + 'Luke 7: the centurion at Capernaum sends elders and friends to ask healing for his servant (kept beside Matthew 8’s direct request); a widow’s son is raised at Nain; John’s messengers come; and a woman anoints Jesus at the house of Simon the Pharisee.', [('Luke 7', 'nt/luke/7')]),
        ('NTE-calls-and-healings-luke-8', 'Calls, healings and crossings (Luke 8)', P + 'Luke 8: Mary Magdalene, Joanna, wife of Chuza, Herod’s steward, and Susanna support the ministry; a storm crossing leads to the country of the Gadarenes opposite Galilee; on the return come Jairus’s only daughter, about twelve, and a woman’s healing.', [('Luke 8', 'nt/luke/8')]),
    ],
    # S3-C1: parable pericopes outside Matthew 13, one view per chapter from the accepted NT chapter ledger, in source order (2/nt)
    'SD0240': [
        ('NTC-parables-matt-18', 'Parables (Matthew 18)', P + 'Matthew 18: teaching on humility, care for little ones, reconciliation and forgiveness includes a parable of a servant.', [('Matthew 18', 'nt/matt/18')]),
        ('NTC-parables-matt-20', 'Parables (Matthew 20)', P + 'Matthew 20: labourers in a vineyard illustrate reward. The vineyard is a story setting, not a mapped estate.', [('Matthew 20', 'nt/matt/20')]),
        ('NTC-parables-matt-22', 'Parables (Matthew 22)', P + 'Matthew 22: amid controversies at the temple, a parable of a wedding feast.', [('Matthew 22', 'nt/matt/22')]),
        ('NTC-parables-matt-25', 'Parables (Matthew 25)', P + 'Matthew 25: the ten virgins, the talents, and the sheep and the goats describe preparedness and judgment.', [('Matthew 25', 'nt/matt/25')]),
        ('NTC-parables-mark-4', 'Parables (Mark 4)', P + 'Mark 4: seed parables taught from a boat beside the sea.', [('Mark 4', 'nt/mark/4')]),
        ('NTC-parables-luke-10', 'Parables (Luke 10)', P + 'Luke 10: the parable of the Samaritan is set on the road from Jerusalem to Jericho. It is a story setting, so no route is drawn.', [('Luke 10', 'nt/luke/10')]),
        ('NTC-parables-luke-12', 'Parables (Luke 12)', P + 'Luke 12: warnings about hypocrisy, possessions and readiness include the rich fool and parables of servants.', [('Luke 12', 'nt/luke/12')]),
        ('NTC-parables-luke-13', 'Parables (Luke 13)', P + 'Luke 13: the fig tree story is a parable, separate from the tower of Siloam and the healed woman in the same chapter.', [('Luke 13', 'nt/luke/13')]),
        ('NTC-parables-luke-14', 'Parables (Luke 14)', P + 'Luke 14: at a Sabbath meal, banquet parables, followed by teaching on the cost of discipleship.', [('Luke 14', 'nt/luke/14')]),
        ('NTC-parables-luke-15', 'Parables (Luke 15)', P + 'Luke 15: the lost sheep, the lost coin and a father’s two sons explain repentance and welcome.', [('Luke 15', 'nt/luke/15')]),
        ('NTC-parables-luke-16', 'Parables (Luke 16)', P + 'Luke 16: the steward, and the rich man and Lazarus, teach about wealth and accountability. This beggar Lazarus is not assumed to be the Lazarus of John 11.', [('Luke 16', 'nt/luke/16')]),
        ('NTC-parables-luke-18', 'Parables (Luke 18)', P + 'Luke 18: the widow and the judge, and the Pharisee and the publican.', [('Luke 18', 'nt/luke/18')]),
        ('NTC-parables-luke-19', 'Parables (Luke 19)', P + 'Luke 19: the parable of the pounds. Its nobleman is not identified with Archelaus.', [('Luke 19', 'nt/luke/19')]),
    ],
    'SD0213': [
        ('NTE-temptations-luke', 'Temptations in Luke’s order', P + 'Luke 4:1–13 gives the temptations in the order wilderness, mountain, Jerusalem, so Luke’s account ends at Jerusalem. A separate source account beside Matthew’s; no merged journey is drawn, and no mountain is located.',
         [('Luke 4:1–13', 'nt/luke/4')]),
    ],
    'SD0226': [
        ('NTE-jerusalem-community-4', 'Peter and John questioned; goods shared (Acts 4)', P + 'Authorities question Peter and John; the believers pray and share their possessions, and Barnabas is introduced as a Levite of Cyprus. His land sale does not locate the land in Cyprus.',
         [('Acts 4', 'nt/acts/4')]),
        ('NTE-jerusalem-community-5', 'Ananias and Sapphira; apostles arrested and released (Acts 5)', P + 'Acts narrates the deaths of Ananias and Sapphira, healings, and the apostles’ arrest and release in Jerusalem. Gamaliel’s remarks on Theudas and Judas are his attributed speech, not a harmonized history, and this Ananias is not the Ananias of Acts 9. No house or prison is located.',
         [('Acts 5', 'nt/acts/5')]),
        ('NTE-jerusalem-community-6', 'The seven chosen (Acts 6)', P + 'A dispute over the daily distribution leads to seven being selected, among them Stephen and Philip; Stephen is then accused before the council, and Acts presents the accusations as false witness. This Philip is not assumed to be the apostle Philip. Acts 6:5 describes Nicolas as a proselyte of Antioch. The regional labels for participants in the dispute in Acts 6:9 are not a narrated journey by Stephen.',
         [('Acts 6', 'nt/acts/6')]),
    ],
    'SD0236': [
        ('NTE-arrest-hearings-22', 'Paul’s defense at Jerusalem (Acts 22)', P + 'Paul recounts his birth in Tarsus, his upbringing at Jerusalem and his Damascus and Jerusalem experiences; his Roman citizenship stops a scourging. Here the companions do not hear the voice, kept beside Acts 9:7, where they hear it; Paul claims citizenship by birth, not purchase.',
         [('Acts 22', 'nt/acts/22')]),
        ('NTE-arrest-hearings-23', 'Council, plot and escort to Caesarea (Acts 23)', P + 'A dispute in the council and a plot follow; Paul’s nephew warns the commander, and Paul is moved under guard from Jerusalem through Antipatris to Caesarea. The nephew is unnamed, and the infantry return from Antipatris while the cavalry continue. Lysias’s letter orders the discovery of Paul’s citizenship differently from the earlier narrative, and this high priest Ananias is a different man. No road is surveyed.',
         [('Acts 23', 'nt/acts/23')]),
        ('NTE-arrest-hearings-24', 'Hearing before Felix (Acts 24)', P + 'Felix hears the charges in Caesarea; Paul stays in custody two years, and Festus succeeds Felix. Felix’s wife Drusilla is named; the bribe Felix hoped for is not said to have been paid. The two years are not converted to a calendar date.',
         [('Acts 24', 'nt/acts/24')]),
        ('NTE-arrest-hearings-25', 'Festus and the appeal to Caesar (Acts 25)', P + 'Festus goes up to Jerusalem and back to Caesarea; Paul appeals to Caesar, and Agrippa and Bernice arrive. Paul does not return to Jerusalem, and “Augustus” is an imperial title here, not the first emperor. The appeal comes before the voyage.',
         [('Acts 25', 'nt/acts/25')]),
        ('NTE-arrest-hearings-26', 'Paul before Agrippa (Acts 26)', P + 'Paul speaks before Agrippa and Bernice, retelling his conversion and mission to the Gentiles; because of the appeal, talk of release does not end his custody. Here all fall to the earth, kept beside Acts 9:7, where the companions stand. Agrippa is not said to be converted.',
         [('Acts 26', 'nt/acts/26')]),
    ],
    'SD0270': [
        ('NTC-vision-sequence-01', 'Revelation 5: the Lamb and the sealed book', P + 'Revelation 5 presents the sealed book (scroll) and the Lamb. A vision scene with no place or date on Earth.',
         [('Revelation 5', 'nt/rev/5')]),
        ('NTC-vision-sequence-02', 'Revelation 6: the seals', P + 'Opening the seals brings riders, martyrs and cosmic disruption. The scene is not identified with any modern war.',
         [('Revelation 6', 'nt/rev/6')]),
        ('NTC-vision-sequence-03', 'Revelation 7: the sealed tribes and the multitude', P + 'The tribes of Israel are sealed, and a multitude stands before the throne. Not a census of present-day peoples.',
         [('Revelation 7', 'nt/rev/7')]),
        ('NTC-vision-sequence-04', 'Revelation 8–9: the trumpets', P + 'The seventh seal opens onto trumpet judgments on earth, sea, waters and heavens; locust and cavalry imagery and angels bound at the Euphrates follow. The Euphrates mention does not locate a historical battle, and no modern disaster site is asserted.',
         [('Revelation 8', 'nt/rev/8'), ('Revelation 9', 'nt/rev/9')]),
        ('NTC-vision-sequence-05', 'Revelation 10: the little book', P + 'A mighty angel stands on sea and land, and the scene of the little book follows. No landing point is located.',
         [('Revelation 10', 'nt/rev/10')]),
        ('NTC-vision-sequence-06', 'Revelation 11: the two witnesses', P + 'The temple is measured, two witnesses prophesy, and the great city is associated with the Lord’s crucifixion; the heavenly temple is opened. The figurative names Sodom and Egypt do not relocate Jerusalem.',
         [('Revelation 11', 'nt/rev/11')]),
        ('NTC-vision-sequence-07', 'Revelation 12: the woman and the dragon', P + 'A woman, a dragon, conflict in heaven and a refuge in the wilderness. The JST identifies the woman with the church, reorders the scene and gives 1,260 years where the KJV has days; no modern date is derived, and the refuge is unlocated.',
         [('Revelation 12', 'nt/rev/12'), ('JST Revelation 12', 'jst/jst-rev/12')]),
        ('NTC-vision-sequence-08', 'Revelation 13: the beasts', P + 'Beasts rise from the sea and from the earth, with worship and number symbolism. No settled modern identification is imposed.',
         [('Revelation 13', 'nt/rev/13')]),
        ('NTC-vision-sequence-09', 'Revelation 14: the Lamb on Zion and the harvest', P + 'The Lamb stands on Zion, angels make proclamations, and harvest imagery follows. Zion here is not automatically a present-day event on Earth.',
         [('Revelation 14', 'nt/rev/14')]),
        ('NTC-vision-sequence-10', 'Revelation 15: the sanctuary', P + 'Victorious worshipers stand by a glassy sea, and the heavenly sanctuary is opened. The glassy sea is given no ocean coordinate.',
         [('Revelation 15', 'nt/rev/15')]),
        ('NTC-vision-sequence-11', 'Revelation 16: the bowls and Armageddon', P + 'Bowls are poured out, the Euphrates dries, and there is a gathering to Armageddon; Babylon is judged. The interpretation of Armageddon is uncertain, and no battle date or route is forecast.',
         [('Revelation 16', 'nt/rev/16')]),
        ('NTC-vision-sequence-12', 'Revelation 17–18: Babylon', P + 'The woman called Babylon and the beast are interpreted with kings and mountains; Babylon’s fall is lamented by kings, merchants and seafarers. Interpretations stay attributed, no single geographic identification is adopted, and the trade list is not a shipping network.',
         [('Revelation 17', 'nt/rev/17'), ('Revelation 18', 'nt/rev/18')]),
        ('NTC-vision-sequence-13', 'Revelation 19: the rider and the supper', P + 'Heavenly praise, the marriage supper, a rider and the defeat of opponents. No contemporary battlefield is placed.',
         [('Revelation 19', 'nt/rev/19')]),
        ('NTC-vision-sequence-14', 'Revelation 20: the millennium and judgment', P + 'The millennium, the judgment, Gog and Magog, and the beloved city. No modern nations are equated, and no chronology chart is drawn.',
         [('Revelation 20', 'nt/rev/20')]),
        ('NTC-vision-sequence-15', 'Revelation 21–22: the new city and the river', P + 'A new heaven and earth, and the New Jerusalem descending with symbolic measurements, gates and foundations; the river and tree of life close the vision. This is the city of the “New Jerusalem (Revelation)” card; its measurements are not drawn as map geometry, and the river is not a modern waterway.',
         [('Revelation 21', 'nt/rev/21'), ('Revelation 22', 'nt/rev/22')]),
    ],
}
